<?php
namespace App\Services;use App\Domain\Imports\ImportStatus;use App\Jobs\PlanImportExecution;use App\Models\{DataImport,ImportExecution};use Illuminate\Support\Facades\DB;
final class StartImportExecution{public function start(DataImport $import,array $snapshot,int $chunkSize=2000):ImportExecution{if($import->status!==ImportStatus::Ready)throw new \DomainException('import_not_ready');$chunkSize=max(100,min(10000,$chunkSize));return DB::transaction(function()use($import,$snapshot,$chunkSize){$execution=ImportExecution::create(['import_id'=>$import->id,'mapping_snapshot_json'=>$snapshot,'status'=>ImportStatus::Queued,'total_rows'=>$import->detected_row_count??0,'chunk_size'=>$chunkSize]);DB::afterCommit(fn()=>PlanImportExecution::dispatch($execution->id)->onQueue('imports-plan'));return $execution;},3);}}
